  "privFooter": "Privacidade e armazenamento",
  "privTitle": "Privacidade e armazenamento do navegador",
  "privClose": "Fechar aviso de privacidade",
  "privWho": "Quem é o responsável?",
  "privWhat": "O que usamos e porquê",
  "privStorage": "Armazenamento do navegador",
  "privOther": "Outras funcionalidades existentes",
  "privProviders": "Prestadores de serviços e transferências internacionais",
  "privRetention": "Conservação e eliminação",
  "privRights": "Os seus direitos",
  "noticeReopen": "Aviso de armazenamento",
  "noticeLabel": "Aviso de armazenamento do navegador",
  "noticeText": "O Cook usa o armazenamento do navegador para as funcionalidades de cozinha e de início de sessão que utiliza. Não é adicionado armazenamento de publicidade nem de análise.",
  "noticeClose": "Fechar aviso de armazenamento",
  "privDraftLabel": "Rascunho — atualizado a 28 de outubro de 2026.",
  "privDraft": "As funcionalidades de conta estão em testes. Os dados do operador e dos serviços abaixo têm de ser completados antes do lançamento público.",
  "privWho1": "O Cook é gerido por [nome legal e morada do operador]. Contacte [endereço de e-mail de privacidade] para questões e pedidos sobre privacidade. Estes dados têm de ser completados antes de o registo abrir.",
  "privWhat1": "Quando cria uma conta, utilizamos o seu e-mail, um identificador de conta, registos de autenticação por palavra-passe e o estado de verificação para fornecer e proteger a sua conta. As palavras-passe são tratadas pelo fornecedor de autenticação como hashes seguros; o Cook não guarda palavras-passe legíveis. Guardamos a disposição da sua cozinha, o idioma escolhido, o tema e as unidades de medida para restaurar as suas definições em todos os dispositivos. É necessário indicar um e-mail e uma palavra-passe para ter conta; pode consultar receitas sem conta.",
  "privWhat2": "O tratamento dos dados da conta e das definições é necessário para prestar o serviço de conta que solicita (artigo 6.º, n.º 1, alínea b), do RGPD). Podem ser tratados registos limitados de segurança e prevenção de abusos com base em interesses legítimos (artigo 6.º, n.º 1, alínea f)), na medida do necessário e após ponderação. Os e-mails de verificação e de reposição da palavra-passe são mensagens de serviço, não marketing. A funcionalidade de conta não acrescenta publicidade nem análise.",
  "privStorage1": "O Cook utiliza sessionStorage para levar a sua cozinha, o progresso na receita e as suas escolhas entre páginas no mesmo separador. Com sessão iniciada, guarda também a sua sessão de autenticação. O navegador normalmente apaga estes dados quando a sessão do separador termina, mas o restauro de sessões do navegador pode mantê-los. Terminar sessão apaga os dados do separador do Cook. O fecho do aviso de armazenamento é guardado apenas nesse separador. Os scripts do próprio Cook não definem cookies. Os seus fornecedores de alojamento ou de serviços podem ter tratamentos de segurança próprios, que têm de ser documentados antes do lançamento.",
  "privStorage2": "OK e o botão de fechar do aviso de armazenamento apenas fecham o aviso. Não autorizam análise, publicidade nem outro rastreio opcional. Qualquer armazenamento não essencial futuro exigirá uma escolha separada antes de começar, com recusa e retirada igualmente fáceis.",
  "privOther1": "A atual funcionalidade de voz da lista de receitas pede ao country.is um país aproximado com base no seu endereço IP para escolher o idioma de voz. Se usar o reconhecimento pelo microfone, o seu navegador pode enviar o áudio ao respetivo fornecedor de reconhecimento de voz. Em alternativa, pode escrever os ingredientes. Estes fornecedores, as suas políticas e a base jurídica destas funcionalidades têm de ser revistos antes do lançamento público.",
  "privProviders1": "Fornecedor de contas previsto: Supabase (PostgreSQL e autenticação geridos), com uma região de base de dados escolhida na UE. Fornecedor de e-mail: [fornecedor]. Alojamento do site: [fornecedor]. O operador tem de confirmar os fornecedores efetivos, os acordos de tratamento, os subcontratantes, a localização dos registos e quaisquer transferências para fora do EEE. Uma região de base de dados na UE não exclui, por si só, transferências internacionais. Quando aplicável, indique a decisão de adequação ou as garantias contratuais aplicáveis e como obter uma cópia.",
  "privRetention1": "As definições da conta são mantidas enquanto a sua conta estiver ativa. Pode pedir a eliminação através do contacto de privacidade acima. Antes do lançamento, o operador tem de definir o processo de resposta aos pedidos de eliminação, a expiração de contas não verificadas e os prazos de conservação dos registos de segurança e das cópias de segurança. Os dados eliminados podem permanecer em cópias de segurança de acesso restrito até ao fim do prazo de conservação documentado.",
  "privRights1": "Consoante as condições aplicáveis, pode pedir acesso, retificação, apagamento, limitação ou portabilidade, ou opor-se ao tratamento baseado em interesses legítimos. Contacte o operador acima; os pedidos são normalmente respondidos no prazo de um mês, sendo explicada qualquer prorrogação legal. Pode apresentar reclamação à sua autoridade de controlo, incluindo a NAIH da Hungria em naih.hu. O Cook não utiliza as definições da conta para decisões automatizadas com efeitos jurídicos ou efeitos igualmente significativos.",
